```rust
#[salsa::tracked(
    returns(deref),
    cycle_initial = |_, _, _| Box::default(),
    heap_size = ruff_memory_usage::heap_size
)]
fn fixture_candidates_from_definition<'db>(
    db: &'db dyn Db,
    definition: Definition<'db>,
) -> Box<[Definition<'db>]> {
    let scope = definition.scope(db);
    let Some(symbol_id) = definition.place(db).as_symbol() else {
        return Box::default();
    };

    let is_stub = definition.file(db).is_stub(db);
    let kind = definition.kind(db);

    if !is_stub
        && !matches!(
            kind,
            DefinitionKind::Function(_)
                | DefinitionKind::ImportFrom(_)
                | DefinitionKind::StarImport(_)
        )
    {
        return Box::default();
    }

    // Evaluate visibility inside the query for the definition's own file.
    let resolution = DefinitionResolution::from_bindings(
        db,
        use_def_map(db, scope).end_of_scope_symbol_bindings(symbol_id),
    );
    if !resolution.definitions().contains(&definition) {
        return Box::default();
    }

    let table = place_table(db, scope);
    let binding_name = table.symbol(symbol_id).name();

    if is_stub
        && let Some(source_file) =
            stub_file_to_real_module(db, definition.program_file(db).resolver_file(db))
                .and_then(|module| module.file(db))
    {
        let source_file = ProgramFile::new(db, source_file, definition.program(db));

        if scope.node(db).scope_kind() == ScopeKind::Class {
            return fixture_candidates_from_stub_class_definition(
                db,
                definition,
                source_file,
            );
        }

        return fixture_candidates_for_name_in_scope(
            db,
            global_scope(db, source_file),
            binding_name,
        );
    }

    if !exists_at_runtime(db, definition) {
        return Box::default();
    }

    match kind {
        DefinitionKind::Function(_) => vec![definition].into_boxed_slice(),

        DefinitionKind::ImportFrom(import) => {
            let parsed = parsed_module(db, definition.python_file(db)).load(db);
            fixture_candidates_from_import(
                db,
                definition,
                import.import(&parsed),
                import.alias(&parsed).name.id(),
            )
        }

        DefinitionKind::StarImport(import) => {
            let parsed = parsed_module(db, definition.python_file(db)).load(db);
            fixture_candidates_from_import(
                db,
                definition,
                import.import(&parsed),
                binding_name,
            )
        }

        _ => Box::default(),
    }
}
```

